-- 05 Logistics Performance
SELECT COUNT(*) AS shipments, SUM(quantity) AS shipped_units, SUM(CASE WHEN actual_delivery_date>promised_delivery_date THEN 1 ELSE 0 END)*1.0/NULLIF(COUNT(actual_delivery_date),0) AS late_rate, AVG(JULIANDAY(actual_delivery_date)-JULIANDAY(promised_delivery_date)) AS avg_delay_days FROM shipments WHERE actual_delivery_date IS NOT NULL;
SELECT status, COUNT(*) AS shipments, SUM(quantity) AS units FROM shipments GROUP BY status ORDER BY shipments DESC;
SELECT warehouse_id, COUNT(*) AS shipments, SUM(quantity) AS units, AVG(JULIANDAY(actual_delivery_date)-JULIANDAY(promised_delivery_date)) AS avg_delay_days, SUM(CASE WHEN actual_delivery_date>promised_delivery_date THEN 1 ELSE 0 END)*1.0/NULLIF(COUNT(actual_delivery_date),0) AS late_rate FROM shipments WHERE actual_delivery_date IS NOT NULL GROUP BY warehouse_id ORDER BY late_rate DESC;
SELECT shipment_id, warehouse_id, customer_id, JULIANDAY(actual_delivery_date)-JULIANDAY(promised_delivery_date) AS delay_days, quantity FROM shipments WHERE actual_delivery_date>promised_delivery_date ORDER BY delay_days DESC;
SELECT warehouse_id, AVG(JULIANDAY(actual_delivery_date)-JULIANDAY(promised_delivery_date)) AS avg_delay_days FROM shipments WHERE actual_delivery_date IS NOT NULL GROUP BY warehouse_id ORDER BY avg_delay_days DESC;
SELECT SUBSTR(ship_date,1,7) AS month, COUNT(*) AS shipments, SUM(quantity) AS units, AVG(JULIANDAY(actual_delivery_date)-JULIANDAY(promised_delivery_date)) AS avg_delay_days FROM shipments WHERE actual_delivery_date IS NOT NULL GROUP BY 1 ORDER BY 1;
SELECT customer_id, COUNT(*) AS shipments, SUM(quantity) AS units, SUM(CASE WHEN actual_delivery_date>promised_delivery_date THEN 1 ELSE 0 END)*1.0/NULLIF(COUNT(actual_delivery_date),0) AS late_rate FROM shipments WHERE actual_delivery_date IS NOT NULL GROUP BY customer_id HAVING COUNT(*)>=5 ORDER BY late_rate DESC;
